      mint_sprig: `${D(LG("mc-sp-g", ["#7FE8BE", "#1FA070"]) + LG("mc-sp-s", ["#5ED6A4", "#27A877"]))}<path d="M32 61V46" stroke="#2B2233" stroke-width="6.5" stroke-linecap="round"/><path d="M32 61V46" stroke="#1E8A66" stroke-width="3" stroke-linecap="round"/><path d="M30 50C18 56 5 51 4 39C16 34 27 40 30 50Z" fill="url(#mc-sp-s)" ${SO}/><path d="M34 50C46 56 59 51 60 39C48 34 37 40 34 50Z" fill="url(#mc-sp-s)" ${SO}/><path d="M28 49C22 45 14 42 9 41M36 49C42 45 50 42 55 41" fill="none" stroke="#B8F5D9" stroke-width="1.7" stroke-linecap="round"/><path d="M32 50C15 41 14 18 32 4C50 18 49 41 32 50Z" fill="url(#mc-sp-g)" ${SO}/>${SH(25, 17, 4, 2.2, -50)}${EYES(27, 37, 28, 2.4)}${SMILE(32, 33, 2.6)}${BLUSH(23, 41, 33)}`,
